using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Central UI relay — same factory/hub pattern as ResourceManager and PlayerInventory: gameplay
/// systems fire an inbound signal (<see cref="SignalShow"/> / <see cref="SignalHide"/> /
/// <see cref="SignalToggle"/>), the manager routes it to the matching reusable panel, then
/// broadcasts an outbound event (<see cref="OnPanelShown"/> / <see cref="OnPanelHidden"/>).
///
/// Callers never reference a concrete screen — they only know a <see cref="UIPanelId"/> and reach
/// the manager through <see cref="Instance"/>. The manager owns the list of reusable panels and
/// reuses them (show/hide), never instantiating per request.
///
/// One per scene. Runs early (negative execution order) so <see cref="Instance"/> and the registry
/// exist before any caller's Awake/OnEnable.
/// </summary>
[DefaultExecutionOrder(-100)]
public class UIManager : MonoBehaviour
{
    public static UIManager Instance { get; private set; }

    [Tooltip("Log each show/hide signal. Off for production.")]
    [SerializeField] private bool _debugLog = true;

    [Tooltip("Reusable panels managed here. Drop UIPanel components in, or Register at runtime.")]
    [SerializeField] private List<UIPanel> _panels = new();

    private readonly Dictionary<UIPanelId, IUIPanel> _registry = new();

    /// <summary>Raised after a panel is shown. Subscribe with += on startup.</summary>
    public event Action<UIPanelId> OnPanelShown;
    /// <summary>Raised after a panel is hidden. Subscribe with += on startup.</summary>
    public event Action<UIPanelId> OnPanelHidden;

    // ── Signals (inbound) ───────────────────────────────────────────────────────

    /// <summary>Signal: show the panel with this id. No-op (warns) if none is registered.</summary>
    public void SignalShow(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (_debugLog) Debug.Log($"[UIManager] show {id}");
        panel.Show();
        OnPanelShown?.Invoke(id);
    }

    /// <summary>Signal: hide the panel with this id.</summary>
    public void SignalHide(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (_debugLog) Debug.Log($"[UIManager] hide {id}");
        panel.Hide();
        OnPanelHidden?.Invoke(id);
    }

    /// <summary>Signal: toggle the panel's visibility.</summary>
    public void SignalToggle(UIPanelId id)
    {
        if (!TryGet(id, out IUIPanel panel)) return;
        if (panel.IsVisible) SignalHide(id);
        else SignalShow(id);
    }

    public bool IsVisible(UIPanelId id) => TryGet(id, out IUIPanel p, warn: false) && p.IsVisible;

    // ── Registration ──────────────────────────────────────────────────────────

    /// <summary>Register a panel at runtime (panels in the serialized list register automatically).</summary>
    public void Register(IUIPanel panel)
    {
        if (panel == null || panel.PanelId == UIPanelId.None) return;
        _registry[panel.PanelId] = panel;
    }

    public void Unregister(IUIPanel panel)
    {
        if (panel == null) return;
        if (_registry.TryGetValue(panel.PanelId, out IUIPanel existing) && existing == panel)
            _registry.Remove(panel.PanelId);
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[UIManager] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;

        foreach (UIPanel panel in _panels)
        {
            if (panel == null) continue;
            if (panel.PanelId == UIPanelId.None)
            {
                Debug.LogWarning($"[UIManager] '{panel.name}' has PanelId.None; skipped.", panel);
                continue;
            }
            Register(panel);
        }
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private bool TryGet(UIPanelId id, out IUIPanel panel, bool warn = true)
    {
        if (_registry.TryGetValue(id, out panel) && panel != null) return true;
        if (warn) Debug.LogWarning($"[UIManager] No panel registered for {id}.", this);
        return false;
    }
}

using UnityEngine;
using UnityEngine.UIElements;
using Flynn.Events;

/// <summary>
/// The always-present player HUD as a single UI Toolkit panel: hotbar, echo-shard counter and the
/// robot battery gauge. A thin controller — the layout lives in PlayerHud.uxml/.uss, this only binds
/// elements and pushes values when the source data raises an event (no polling).
///
/// Driven by: <see cref="PlayerInventory"/> (hotbar), an <see cref="IntVariable"/> for echo shards
/// and an <see cref="IntVariable"/> (0–100) for the battery. Registered with <see cref="UIManager"/>
/// as <see cref="UIPanelId.Hud"/>; left visible the whole game.
/// </summary>
public class PlayerHudPanel : UIToolkitPanel
{
    [Header("Sources (echo/battery are asset refs; inventory falls back to Instance)")]
    [SerializeField] private PlayerInventory _inventory;
    [SerializeField] private IntVariable _echoShards;
    [SerializeField] private IntVariable _battery; // 0..100

    private readonly VisualElement[] _slots = new VisualElement[InventoryData.SlotCount];
    private readonly VisualElement[] _icons = new VisualElement[InventoryData.SlotCount];
    private readonly Label[] _counts = new Label[InventoryData.SlotCount];

    private Label _echoLabel;
    private VisualElement _batteryFill;
    private Label _batteryLabel;

    // ── Unity messages ────────────────────────────────────────────────────────

    protected override void OnEnable()
    {
        base.OnEnable();

        if (_inventory == null) _inventory = PlayerInventory.Instance;
        if (_inventory != null)
        {
            _inventory.OnSlotChanged       += RefreshSlot;
            _inventory.OnActiveSlotChanged += RefreshActiveSlot;
        }
        if (_echoShards != null) _echoShards.OnChanged += SetEcho;
        if (_battery    != null) _battery.OnChanged    += SetBattery;

        // Also subscribe to GameEventBus for currency collection feedback
        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Subscribe<CurrencyCollected>(OnCurrencyCollected);
    }

    private void OnDisable()
    {
        if (_inventory != null)
        {
            _inventory.OnSlotChanged       -= RefreshSlot;
            _inventory.OnActiveSlotChanged -= RefreshActiveSlot;
        }
        if (_echoShards != null) _echoShards.OnChanged -= SetEcho;
        if (_battery    != null) _battery.OnChanged    -= SetBattery;

        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Unsubscribe<CurrencyCollected>(OnCurrencyCollected);
    }

    // ── Binding ─────────────────────────────────────────────────────────────────

    protected override bool Bind(VisualElement root)
    {
        if (root.Q<VisualElement>("Slot_0") == null) return false; // tree not ready yet

        for (int i = 0; i < InventoryData.SlotCount; i++)
        {
            _slots[i]  = root.Q<VisualElement>($"Slot_{i}");
            _icons[i]  = root.Q<VisualElement>($"Icon_{i}");
            _counts[i] = root.Q<Label>($"Count_{i}");
        }
        _echoLabel    = root.Q<Label>("EchoCount");
        _batteryFill  = root.Q<VisualElement>("BatteryFill");
        _batteryLabel = root.Q<Label>("BatteryLabel");
        return true;
    }

    protected override void OnBound()
    {
        RefreshAll();
        if (_echoShards != null) SetEcho(_echoShards.Value);
        if (_battery    != null) SetBattery(_battery.Value);
    }

    // ── Refresh (event-driven) ──────────────────────────────────────────────────

    private void RefreshAll()
    {
        if (Root == null || _inventory == null) return;
        for (int i = 0; i < InventoryData.SlotCount && i < _inventory.SlotCount; i++) RefreshSlot(i);
        RefreshActiveSlot(_inventory.ActiveSlotIndex);
    }

    private void RefreshSlot(int i)
    {
        if (Root == null || i < 0 || i >= InventoryData.SlotCount) return;
        if (_icons[i] == null) return;

        InventorySlot slot = _inventory.GetSlot(i);
        bool hasItem = !slot.IsEmpty;

        if (hasItem && slot.item.icon != null)
        {
            _icons[i].style.backgroundImage = new StyleBackground(slot.item.icon);
            _icons[i].style.display = DisplayStyle.Flex;
        }
        else
        {
            _icons[i].style.backgroundImage = StyleKeyword.None;
            _icons[i].style.display = DisplayStyle.None;
        }

        if (_counts[i] != null)
        {
            bool show = hasItem && slot.count > 1;
            _counts[i].text = show ? slot.count.ToString() : string.Empty;
            _counts[i].style.display = show ? DisplayStyle.Flex : DisplayStyle.None;
        }
    }

    private void RefreshActiveSlot(int active)
    {
        if (Root == null) return;
        for (int i = 0; i < InventoryData.SlotCount; i++)
        {
            if (_slots[i] == null) continue;
            if (i == active) _slots[i].AddToClassList("hotbar-slot--active");
            else             _slots[i].RemoveFromClassList("hotbar-slot--active");
        }
    }

    private void SetEcho(int value)
    {
        if (_echoLabel != null) _echoLabel.text = value.ToString();
    }

    private void SetBattery(int value)
    {
        int pct = Mathf.Clamp(value, 0, 100);
        if (_batteryFill != null) _batteryFill.style.width = new StyleLength(Length.Percent(pct));
        if (_batteryLabel != null) _batteryLabel.text = pct + "%";
    }

    private void OnCurrencyCollected(CurrencyCollected evt)
    {
        // The IntVariable already drives SetEcho via OnChanged, but this gives us
        // a hook for future sparkle animations / sound triggers at the HUD level.
    }
}

using UnityEngine;
using UnityEngine.UIElements;

/// <summary>
/// Base for UI Toolkit panels driven by <see cref="UIManager"/>. Wraps the one fragile part of
/// UI Toolkit — element binding — in the proven defense: the visual tree may not exist during
/// OnEnable (component order isn't guaranteed), so <see cref="Bind"/> is retried from Update until
/// it succeeds. Subclasses query/cache elements in Bind and never touch the tree before it's ready.
///
/// Show/Hide toggle the root's <c>display</c> instead of the GameObject, so the UIDocument stays
/// alive and we never rebuild + rebind the tree on every show (which is what made the old HUD
/// flaky). The GameObject itself stays active.
/// </summary>
[RequireComponent(typeof(UIDocument))]
public abstract class UIToolkitPanel : UIPanel
{
    [Tooltip("Visible as soon as it binds (always-present HUD = true; pop-ups like the hover tag = false).")]
    [SerializeField] private bool _startVisible = true;

    protected UIDocument Document { get; private set; }
    protected VisualElement Root { get; private set; }

    private bool _bound;

    // ── Unity messages ────────────────────────────────────────────────────────

    protected virtual void Awake()
    {
        Document = GetComponent<UIDocument>();
        IsVisible = _startVisible;
    }

    protected virtual void OnEnable()
    {
        _bound = false;
        TryBind();
    }

    protected virtual void Update()
    {
        if (!_bound) TryBind();
    }

    // ── Show / hide (display toggle, document stays alive) ──────────────────────

    public override void Show()
    {
        IsVisible = true;
        ApplyDisplay();
        OnShow();
    }

    public override void Hide()
    {
        IsVisible = false;
        ApplyDisplay();
        OnHide();
    }

    // ── Binding ─────────────────────────────────────────────────────────────────

    /// <summary>Query and cache elements. Return false if the tree isn't built yet (retried next frame).</summary>
    protected abstract bool Bind(VisualElement root);

    /// <summary>Called once after a successful bind — do the first data refresh here.</summary>
    protected virtual void OnBound() { }

    private void TryBind()
    {
        if (Document == null) return;
        VisualElement root = Document.rootVisualElement;
        if (root == null) return;
        if (!Bind(root)) return; // sentinel element missing → tree not ready, try again next frame

        Root = root;
        _bound = true;
        ApplyDisplay();
        OnBound();
    }

    private void ApplyDisplay()
    {
        if (Root != null)
            Root.style.display = IsVisible ? DisplayStyle.Flex : DisplayStyle.None;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Robot energy system. Owns a 0–100 <see cref="IntVariable"/> battery and drains it
/// both passively (over time) and actively (from gameplay actions via <see cref="BatterySettings"/>).
/// The HUD reads the battery purely through <see cref="IntVariable.OnChanged"/>.
///
/// Supports a configurable <see cref="BatterySettings"/> SO for action costs and an
/// <c>infiniteBatteryDebug</c> toggle for sandbox testing without battery interference.
/// </summary>
[DefaultExecutionOrder(-40)]
public class RobotBattery : MonoBehaviour
{
    public const int Min = 0;
    public const int Max = 100;

    public static RobotBattery Instance { get; private set; }

    [Tooltip("The shared 0–100 battery value the HUD displays. Assign the same asset on PlayerHudPanel.")]
    [SerializeField] private IntVariable _battery;

    [Tooltip("Battery settings: action costs, passive drain, debug mode.")]
    [SerializeField] private BatterySettings _settings;

    [SerializeField, Range(Min, Max)] private int _startCharge = 100;

    [Tooltip("Passive drain in battery points per second. Overridden by BatterySettings if assigned.")]
    [SerializeField] private float _drainPerSecond = 1f;

    [SerializeField] private bool _autoDrain = true;

    private float _accum;

    // ── API ──────────────────────────────────────────────────────────────────

    public int Charge => _battery != null ? _battery.Value : 0;
    public bool IsEmpty => Charge <= Min;
    public bool IsFull  => Charge >= Max;

    /// <summary>Whether infinite battery debug mode is active.</summary>
    public bool InfiniteDebug => _settings != null && _settings.infiniteBatteryDebug;

    /// <summary>Access to battery settings for cost lookups (read-only).</summary>
    public BatterySettings Settings => _settings;

    /// <summary>
    /// Can the battery afford this cost? Returns true if infinite debug is on,
    /// or if there's enough charge (as a float, so partial charges are possible).
    /// </summary>
    public bool CanSpend(float cost)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return true;
        return Charge >= cost;
    }

    /// <summary>
    /// Spend a float amount of battery (for action costs). No-op in infinite debug mode.
    /// Publishes <see cref="BatteryChanged"/> and threshold events.
    /// </summary>
    public void Spend(float cost)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return;
        if (cost <= 0f) return;
        _accum -= cost;
        FlushAccum();
    }

    /// <summary>Drain over time (continuous actions like pulling/scanning).</summary>
    public void DrainOverTime(float costPerSecond)
    {
        if (_settings != null && _settings.infiniteBatteryDebug) return;
        _accum -= costPerSecond * Time.deltaTime;
        FlushAccum();
    }

    /// <summary>Add charge (negative to drain). Clamped to 0–100; notifies via the IntVariable.</summary>
    public void AddCharge(int amount) => SetCharge(Charge + amount);

    /// <summary>Drain charge by a positive amount.</summary>
    public void Drain(int amount) => SetCharge(Charge - Mathf.Abs(amount));

    public void SetCharge(int value)
    {
        if (_battery == null) return;
        int prev = Charge;
        _battery.Value = Mathf.Clamp(value, Min, Max);
        int current = Charge;

        if (GameEventBus.Instance != null)
        {
            GameEventBus.Instance.Publish(new BatteryChanged(current, Max));
            if (current <= Min && prev > Min)
                GameEventBus.Instance.Publish(new BatteryEmpty());
            else if (current <= LowThreshold && prev > LowThreshold)
                GameEventBus.Instance.Publish(new BatteryLow(current, (float)current / Max));
        }
    }

    public void SetAutoDrain(bool on) => _autoDrain = on;

    private int LowThreshold => _settings != null ? _settings.lowBatteryThreshold : 20;

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[RobotBattery] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
        SetCharge(_startCharge);
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (!_autoDrain || _battery == null || IsEmpty) return;

        float drainRate = _settings != null && _settings.enablePassiveDrain
            ? _settings.passiveDrainPerSecond
            : _drainPerSecond;

        if (drainRate <= 0f) return;

        _accum -= drainRate * Time.deltaTime;
        FlushAccum();
    }

    /// <summary>Flush accumulated fractional drain to the integer battery value.</summary>
    private void FlushAccum()
    {
        if (_accum >= 0f) return;
        int whole = Mathf.FloorToInt(-_accum);
        if (whole <= 0) return;
        _accum += whole;
        Drain(whole);
    }
}

using UnityEngine;

/// <summary>
/// Configurable battery cost model. Designers can toggle passive drain, set per-action
/// costs, and enable infinite battery debug mode for sandbox testing without the
/// battery constantly interfering.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Player/Battery Settings", fileName = "BatterySettings")]
public class BatterySettings : ScriptableObject
{
    [Header("Passive Drain")]
    [Tooltip("Whether the battery drains passively over time.")]
    public bool enablePassiveDrain = true;
    [Tooltip("Battery points drained per second while passive drain is enabled.")]
    public float passiveDrainPerSecond = 0.5f;

    [Header("Action Costs")]
    [Tooltip("Whether actions drain the battery.")]
    public bool enableActionDrain = true;

    [Tooltip("Battery cost per wrench swing.")]
    public float swingCost = 2f;
    [Tooltip("Battery cost per wrench throw.")]
    public float throwCost = 5f;
    [Tooltip("Battery cost to start a grapple (flat).")]
    public float grappleCost = 8f;
    [Tooltip("Battery cost per second while actively pulling with the rope.")]
    public float pullCostPerSecond = 3f;
    [Tooltip("Battery cost per second while scanning (future).")]
    public float scanCostPerSecond = 5f;
    [Tooltip("Battery cost per second while restoring (future).")]
    public float restoreCostPerSecond = 5f;

    [Header("Thresholds")]
    [Tooltip("Battery level (0-100) below which the BatteryLow event fires.")]
    public int lowBatteryThreshold = 20;

    [Header("Debug")]
    [Tooltip("When true, CanSpend always returns true and Spend is a no-op. For sandbox testing.")]
    public bool infiniteBatteryDebug = false;
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Left-click swing for the wrench multitool. Simple tap with a short cooldown
/// to prevent spam. The swing faces the mouse aim point. Routes damage through
/// the ResourceManager observer pattern. Disabled while the wrench is airborne (thrown).
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchSwingController : MonoBehaviour
{
    private const int WrenchAnimIndex = 4;

    [SerializeField] private WrenchConfig _config;
    [Tooltip("Optional — used to block swinging while the wrench is mid-throw.")]
    [SerializeField] private WrenchThrowController _throw;

    [Tooltip("Directional swipe arc visual. Fed the player→mouse direction on each swing.")]
    [SerializeField] private WrenchSwingArc _swingArc;

    [Tooltip("Cooldown between swings (seconds).")]
    [SerializeField] private float _cooldownTime = 0.1f;

    private PlayerMouseAimer _aimer;
    private PlayerInitializer _playerInit;
    private IPlayerVisual _animDriver;
    private RobotBattery _battery;
    private float _cooldown;

    public bool IsCharging => false;
    public float ChargeNormalized => 0f;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _playerInit = GetComponent<PlayerInitializer>();
        _battery    = RobotBattery.Instance;
    }

    private void Update()
    {
        if (_cooldown > 0f) _cooldown -= Time.deltaTime;

        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && (_throw == null || !_throw.IsAirborne);
        if (!usable) return;

        if (Input.GetMouseButtonDown(0) && _cooldown <= 0f)
            DoSwing();
    }

    private void DoSwing()
    {
        // Battery cost check
        float swingCost = _battery != null && _battery.Settings != null
            ? _battery.Settings.swingCost : 0f;
        if (_battery != null && !_battery.CanSpend(swingCost)) return;

        if (_animDriver != null)
            _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);

        int animIndex = _aimer.SwingAnimIndex;
        if (animIndex <= 0) animIndex = WrenchAnimIndex;

        float speed = _config != null ? _config.lightSwingAnimSpeed : 1.0f;
        if (_animDriver != null)
            _animDriver.ReleaseSwing(animIndex, speed);

        if (_swingArc != null)
            _swingArc.Play(_aimer.WorldAimPoint);

        _cooldown = _cooldownTime;

        // Route hit through the ResourceManager observer pattern.
        int damage = _config != null ? _config.lightSwingDamage : 1;
        GameObject target = _aimer.HoveredGameObject;
        if (_playerInit != null && damage > 0)
            _playerInit.EmitHit(_aimer.WorldAimPoint, target, damage);

        // Publish swing event
        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;
        PublishEvent(new ToolSwingStarted(tool, _aimer.WorldAimPoint));

        // Spend battery after successful swing
        if (_battery != null && swingCost > 0f) _battery.Spend(swingCost);
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Right-click throw for the wrench. Tap = short throw; hold to charge for a longer
/// throw (distance scales min→max with charge). Spawns a ThrownWrench projectile that
/// flies to the target, hovers, then boomerangs back to the player and is caught.
/// Only one throw may be airborne at a time. Exposes IsCharging / ChargeNormalized /
/// IsAirborne for the aim reticle and the swing controller.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchThrowController : MonoBehaviour
{
    [SerializeField] private WrenchConfig _config;
    [SerializeField] private GameObject _thrownWrenchPrefab;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private ThrownWrench _airborne;
    private float _chargeTimer;
    private bool _charging;

    public bool IsCharging => _charging;
    public bool IsAirborne => _airborne != null;
    public float ChargeNormalized => _config != null && _config.throwChargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.throwChargeTime)
        : 0f;

    /// <summary>
    /// World-space hand position: the billboard visual centre, so the wrench
    /// appears to leave from and return to the sprite rather than the physics root.
    /// </summary>
    public Vector3 CatchPoint =>
        _animDriver != null ? _animDriver.VisualCenter : transform.position;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
    }

    private void Update()
    {
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !IsAirborne;
        if (!usable)
        {
            _charging = false;
            _chargeTimer = 0f;
            return;
        }

        if (Input.GetMouseButtonDown(1))
        {
            _charging = true;
            _chargeTimer = 0f;
        }
        else if (_charging && Input.GetMouseButton(1))
        {
            _chargeTimer += Time.deltaTime;
        }
        else if (_charging && Input.GetMouseButtonUp(1))
        {
            DoThrow();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void DoThrow()
    {
        // Battery cost check
        var battery = RobotBattery.Instance;
        float throwCost = battery != null && battery.Settings != null
            ? battery.Settings.throwCost : 0f;
        if (battery != null && !battery.CanSpend(throwCost)) return;

        if (_thrownWrenchPrefab == null || _config == null) return;

        // Use the billboard's visual centre as origin so distance/direction is
        // measured from where the sprite appears on screen, not from the feet.
        Vector3 origin = CatchPoint;

        // Direction on the XZ plane from the visual centre to the aim point.
        Vector3 toAim = _aimer.WorldAimPoint - origin;
        toAim.y = 0f;
        if (toAim.sqrMagnitude < 0.0001f) toAim = transform.forward;

        // Charge gates maximum reach. If the cursor is closer than that, the wrench
        // lands exactly on it; if farther, it stops at the charge-limited range.
        float maxDist = Mathf.Lerp(_config.minThrowDistance, _config.maxThrowDistance, ChargeNormalized);
        float dist = Mathf.Min(toAim.magnitude, maxDist);

        Vector3 target = origin + toAim.normalized * dist;
        // Restore the aim Y so the wrench lands at the actual world surface height.
        target.y = _aimer.WorldAimPoint.y;

        GameObject go = Instantiate(_thrownWrenchPrefab, CatchPoint, Quaternion.identity);
        _airborne = go.GetComponent<ThrownWrench>();
        if (_airborne != null) _airborne.Launch(this, target, _config);
        else Destroy(go);

        // Spend battery after successful throw
        if (battery != null && throwCost > 0f) battery.Spend(throwCost);

        // Publish throw events
        if (GameEventBus.Instance != null)
        {
            GameEventBus.Instance.Publish(new ToolThrowReleased(target, ChargeNormalized));
        }
    }

