using UnityEngine;
using Flynn.Events;

/// <summary>
/// Left-click swing for the wrench multitool. Simple tap with a short cooldown
/// to prevent spam. The swing faces the mouse aim point. Routes damage through
/// the ResourceManager observer pattern. Disabled while the wrench is airborne (thrown).
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchSwingController : MonoBehaviour
{
    private const int WrenchAnimIndex = 4;

    [SerializeField] private WrenchConfig _config;
    [Tooltip("Optional — used to block swinging while the wrench is mid-throw.")]
    [SerializeField] private WrenchThrowController _throw;

    [Tooltip("Directional swipe arc visual. Fed the player→mouse direction on each swing.")]
    [SerializeField] private WrenchSwingArc _swingArc;

    [Tooltip("Cooldown between swings (seconds).")]
    [SerializeField] private float _cooldownTime = 0.1f;

    private PlayerMouseAimer _aimer;
    private PlayerInitializer _playerInit;
    private IPlayerVisual _animDriver;
    private RobotBattery _battery;
    private float _cooldown;

    public bool IsCharging => false;
    public float ChargeNormalized => 0f;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _playerInit = GetComponent<PlayerInitializer>();
        _battery    = RobotBattery.Instance;
    }

    private void Update()
    {
        if (_cooldown > 0f) _cooldown -= Time.deltaTime;

        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && (_throw == null || !_throw.IsAirborne);
        if (!usable) return;

        if (Input.GetMouseButtonDown(0) && _cooldown <= 0f)
            DoSwing();
    }

    private void DoSwing()
    {
        // Battery cost check
        float swingCost = _battery != null && _battery.Settings != null
            ? _battery.Settings.swingCost : 0f;
        if (_battery != null && !_battery.CanSpend(swingCost)) return;

        if (_animDriver != null)
            _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);

        int animIndex = _aimer.SwingAnimIndex;
        if (animIndex <= 0) animIndex = WrenchAnimIndex;

        float speed = _config != null ? _config.lightSwingAnimSpeed : 1.0f;
        if (_animDriver != null)
            _animDriver.ReleaseSwing(animIndex, speed);

        if (_swingArc != null)
            _swingArc.Play(_aimer.WorldAimPoint);

        _cooldown = _cooldownTime;

        // Route hit through the ResourceManager observer pattern.
        int damage = _config != null ? _config.lightSwingDamage : 1;
        GameObject target = _aimer.HoveredGameObject;
        if (_playerInit != null && damage > 0)
            _playerInit.EmitHit(_aimer.WorldAimPoint, target, damage);

        // Publish swing event
        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;
        PublishEvent(new ToolSwingStarted(tool, _aimer.WorldAimPoint));

        // Spend battery after successful swing
        if (_battery != null && swingCost > 0f) _battery.Spend(swingCost);
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Right-click throw for the wrench. Tap = short throw; hold to charge for a longer
/// throw (distance scales min→max with charge). Spawns a ThrownWrench projectile that
/// flies to the target, hovers, then boomerangs back to the player and is caught.
/// Only one throw may be airborne at a time. Exposes IsCharging / ChargeNormalized /
/// IsAirborne for the aim reticle and the swing controller.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchThrowController : MonoBehaviour
{
    [SerializeField] private WrenchConfig _config;
    [SerializeField] private GameObject _thrownWrenchPrefab;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private ThrownWrench _airborne;
    private float _chargeTimer;
    private bool _charging;

    public bool IsCharging => _charging;
    public bool IsAirborne => _airborne != null;
    public float ChargeNormalized => _config != null && _config.throwChargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.throwChargeTime)
        : 0f;

    /// <summary>
    /// World-space hand position: the billboard visual centre, so the wrench
    /// appears to leave from and return to the sprite rather than the physics root.
    /// </summary>
    public Vector3 CatchPoint =>
        _animDriver != null ? _animDriver.VisualCenter : transform.position;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
    }

    private void Update()
    {
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !IsAirborne;
        if (!usable)
        {
            _charging = false;
            _chargeTimer = 0f;
            return;
        }

        if (Input.GetMouseButtonDown(1))
        {
            _charging = true;
            _chargeTimer = 0f;
        }
        else if (_charging && Input.GetMouseButton(1))
        {
            _chargeTimer += Time.deltaTime;
        }
        else if (_charging && Input.GetMouseButtonUp(1))
        {
            DoThrow();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void DoThrow()
    {
        // Battery cost check
        var battery = RobotBattery.Instance;
        float throwCost = battery != null && battery.Settings != null
            ? battery.Settings.throwCost : 0f;
        if (battery != null && !battery.CanSpend(throwCost)) return;

        if (_thrownWrenchPrefab == null || _config == null) return;

        // Use the billboard's visual centre as origin so distance/direction is
        // measured from where the sprite appears on screen, not from the feet.
        Vector3 origin = CatchPoint;

        // Direction on the XZ plane from the visual centre to the aim point.
        Vector3 toAim = _aimer.WorldAimPoint - origin;
        toAim.y = 0f;
        if (toAim.sqrMagnitude < 0.0001f) toAim = transform.forward;

        // Charge gates maximum reach. If the cursor is closer than that, the wrench
        // lands exactly on it; if farther, it stops at the charge-limited range.
        float maxDist = Mathf.Lerp(_config.minThrowDistance, _config.maxThrowDistance, ChargeNormalized);
        float dist = Mathf.Min(toAim.magnitude, maxDist);

        Vector3 target = origin + toAim.normalized * dist;
        // Restore the aim Y so the wrench lands at the actual world surface height.
        target.y = _aimer.WorldAimPoint.y;

        GameObject go = Instantiate(_thrownWrenchPrefab, CatchPoint, Quaternion.identity);
        _airborne = go.GetComponent<ThrownWrench>();
        if (_airborne != null) _airborne.Launch(this, target, _config);
        else Destroy(go);

        // Spend battery after successful throw
        if (battery != null && throwCost > 0f) battery.Spend(throwCost);

        // Publish throw events
        if (GameEventBus.Instance != null)
        {
            GameEventBus.Instance.Publish(new ToolThrowReleased(target, ChargeNormalized));
        }
    }

    /// <summary>Called by ThrownWrench when it has returned and been caught.</summary>
    public void OnCaught() => _airborne = null;
}

