using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Central typed event bus for gameplay events. Systems publish; managers subscribe.
/// Events are plain C# structs (zero-alloc publish). One per scene on MANAGERS.
/// </summary>
[DefaultExecutionOrder(-110)]
public class GameEventBus : MonoBehaviour
{
    public static GameEventBus Instance { get; private set; }

    private readonly Dictionary<Type, List<Delegate>> _subscribers = new();

    [Tooltip("Log every published event type. Off for production.")]
    [SerializeField] private bool _debugLog;

    // ── Subscribe / Unsubscribe ──────────────────────────────────────────────

    /// <summary>Subscribe a handler for event type T.</summary>
    public void Subscribe<T>(Action<T> handler) where T : struct
    {
        var type = typeof(T);
        if (!_subscribers.TryGetValue(type, out var list))
        {
            list = new List<Delegate>();
            _subscribers[type] = list;
        }
        list.Add(handler);
    }

    /// <summary>Unsubscribe a handler for event type T.</summary>
    public void Unsubscribe<T>(Action<T> handler) where T : struct
    {
        var type = typeof(T);
        if (_subscribers.TryGetValue(type, out var list))
            list.Remove(handler);
    }

    // ── Publish ─────────────────────────────────────────────────────────────

    /// <summary>Publish an event to all subscribers of type T.</summary>
    public void Publish<T>(T evt) where T : struct
    {
        if (_debugLog) Debug.Log($"[GameEventBus] {typeof(T).Name}");
        if (!_subscribers.TryGetValue(typeof(T), out var list)) return;
        for (int i = 0; i < list.Count; i++)
        {
            try { ((Action<T>)list[i]).Invoke(evt); }
            catch (Exception e) { Debug.LogException(e); }
        }
    }

    // ── Singleton ────────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[GameEventBus] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }
}

using UnityEngine;

/// <summary>
/// The visual/animation surface the player's combat &amp; interaction controllers drive,
/// decoupled from how the body is actually rendered. Implemented by both the legacy
/// sprite-sheet driver (<see cref="FlynnAnimationDriver"/>) and the procedural cube-rig
/// driver (<see cref="ProceduralCharacterDriver"/>) so the same wrench/throw/rope/reticle
/// logic works against either body without edits.
///
/// Controllers resolve it via <c>GetComponent&lt;IPlayerVisual&gt;()</c> in Awake.
/// </summary>
public interface IPlayerVisual
{
    /// <summary>World-space "hand" / chest origin for thrown projectiles and the rope end.</summary>
    Vector3 VisualCenter { get; }

    /// <summary>VisualCenter projected to the character's foot Y (ground-plane indicators).</summary>
    Vector3 VisualGroundCenter { get; }

    /// <summary>True while an attack/swing is playing (gates re-triggering).</summary>
    bool IsAttacking { get; }

    /// <summary>Fire the attack pose for the given tool index (1=pick 2=axe 3=hammer 4=wrench).</summary>
    void TriggerAttack(int animIndex);

    /// <summary>Enter the windup hold for the given tool index.</summary>
    void BeginChargePose(int animIndex);

    /// <summary>Scrub the windup pose with charge fraction 0→1 (also live-swaps the tool).</summary>
    void UpdateChargePose(int animIndex, float charge01);

    /// <summary>Release the swing at the given playback speed (higher = faster follow-through).</summary>
    void ReleaseSwing(int animIndex, float animSpeed);

    /// <summary>Abort a windup and return to neutral.</summary>
    void CancelSwing();

    /// <summary>Orient the body toward a world-space XZ direction. Ignores Y; no-op on zero.</summary>
    void FaceWorldDirection(Vector3 worldDir);
}

using UnityEngine;

/// <summary>
/// Stable identity for a reusable UI screen/widget. Enum instead of a string key so routing
/// through <see cref="UIManager"/> has no magic strings and shows up in the Inspector as a dropdown.
/// Extend as screens are added.
/// </summary>
public enum UIPanelId
{
    None = 0,
    Hud,
    Inventory,
    Dialogue,
    Pause,
    InteractTag,
    ResourceHP,
}

/// <summary>
/// A reusable UI component the <see cref="UIManager"/> can show/hide by <see cref="UIPanelId"/>.
/// Implemented as an interface so the manager never depends on a concrete screen type.
/// </summary>
public interface IUIPanel
{
    UIPanelId PanelId { get; }
    bool IsVisible { get; }
    void Show();
    void Hide();
}

/// <summary>
/// Base class for reusable UI screens driven by <see cref="UIManager"/>. Default Show/Hide just
/// toggles the GameObject; override <see cref="OnShow"/> / <see cref="OnHide"/> for animation,
/// data binding, focus, etc. A concrete screen (e.g. an inventory panel) extends this, picks its
/// <see cref="UIPanelId"/> in the Inspector, and gets registered with the manager — either by
/// being dropped into the manager's serialized list, or via runtime <see cref="UIManager.Register"/>.
/// </summary>
public abstract class UIPanel : MonoBehaviour, IUIPanel
{
    [SerializeField] private UIPanelId _panelId = UIPanelId.None;

    public UIPanelId PanelId => _panelId;
    public bool IsVisible { get; protected set; }

    public virtual void Show()
    {
        if (IsVisible) return;
        gameObject.SetActive(true);
        IsVisible = true;
        OnShow();
    }

    public virtual void Hide()
    {
        if (!IsVisible) return;
        OnHide();
        IsVisible = false;
        gameObject.SetActive(false);
    }

    /// <summary>Called after the panel becomes visible. Bind data / play intro here.</summary>
    protected virtual void OnShow() { }

    /// <summary>Called before the panel hides. Clean up / play outro here.</summary>
    protected virtual void OnHide() { }
}
